// Every raster asset is pre-generated by Shed Dev Sprites. Vite bundles these URLs.
const assets = import.meta.glob('../public/sprites/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;
const atlasJsons = import.meta.glob('../public/sprites/*-atlas.json', { eager: true, import: 'default' }) as Record<string, AtlasMeta>;
const blobJsons = import.meta.glob('../public/sprites/*-blob47.json', { eager: true, import: 'default' }) as Record<string, BlobMeta>;

export interface AtlasMeta {
  actions: string[];
  directions: string[];
  cell: number;
  cols: number;
  rows: number;
}

export interface BlobMeta {
  cell_size: number;
  cols: number;
  rows: number;
  masks: number[];
  mask_to_index: Record<string, number>;
}

export function spriteUrl(name: string) {
  return assets[`../public/sprites/${name}.png`];
}

export const IMG = {
  titleBg: spriteUrl('scene-title'),
  humanCrest: spriteUrl('human-melee-0'),
  darkelfCrest: spriteUrl('darkelf-melee-0'),
  corruptedCrest: spriteUrl('corrupted-melee-0'),
  woodPanel: spriteUrl('wood'),
  victory: spriteUrl('scene-victory'),
  defeat: spriteUrl('scene-defeat'),
};

const images = new Map<string, HTMLImageElement>();
export function sprite(name: string) {
  let img = images.get(name);
  if (!img) {
    const url = spriteUrl(name);
    if (!url) return null;
    img = new Image();
    img.src = url;
    images.set(name, img);
  }
  return img.complete && img.naturalWidth ? img : null;
}

export function atlasMeta(name: string): AtlasMeta | null {
  return atlasJsons[`../public/sprites/${name}.json`] ?? null;
}

export function blobTileIndex(kind: string, mask: number): number {
  const meta = blobJsons[`../public/sprites/${kind}-blob47.json`];
  if (!meta) return 0;
  return meta.mask_to_index[String(mask)] ?? 0;
}
